class Solution:
    def lengthOfLongestSubstring(self, s: str) -> int:
        window: set[str] = set()
        l = 0
        best = 0
        for r in range(len(s)):
            while s[r] in window:
                window.remove(s[l])  # viz:shrink
                l += 1
            window.add(s[r])  # viz:grow
            best = max(best, r - l + 1)
        return best  # viz:done
